package techguns.damage;

import net.minecraft.core.registries.Registries;
import net.minecraft.data.worldgen.BootstrapContext;
import net.minecraft.resources.ResourceKey;
import net.minecraft.world.damagesource.DamageEffects;
import net.minecraft.world.damagesource.DamageScaling;
import net.minecraft.world.damagesource.DamageType;
import techguns.TGIds;
import techguns.Techguns;
import techguns.core.damage.TGDamageCategory;

/**
 * Techguns damage types (datapack registry). Entries are generated by datagen from {@link #bootstrap}.
 * Their {@link TGDamageCategory} comes from the category tags in {@link TGDamageTypeTags}.
 */
public final class TGDamageTypes {
    public static final ResourceKey<DamageType> BULLET = key("bullet");
    public static final ResourceKey<DamageType> EXPLOSION = key("explosion");
    public static final ResourceKey<DamageType> FIRE = key("fire");
    public static final ResourceKey<DamageType> ENERGY = key("energy");
    public static final ResourceKey<DamageType> POISON = key("poison");
    public static final ResourceKey<DamageType> ICE = key("ice");
    public static final ResourceKey<DamageType> LIGHTNING = key("lightning");
    public static final ResourceKey<DamageType> RADIATION = key("radiation");
    /** Lethal radiation poisoning; ignores armor. */
    public static final ResourceKey<DamageType> RADIATION_POISONING = key("radiation_poisoning");
    public static final ResourceKey<DamageType> DARK = key("dark");
    /** Melee hits from Techguns weapons. */
    public static final ResourceKey<DamageType> PHYSICAL = key("physical");

    private TGDamageTypes() {
    }

    private static ResourceKey<DamageType> key(String name) {
        return ResourceKey.create(Registries.DAMAGE_TYPE, TGIds.id(name));
    }

    /** Message id, used as {@code death.attack.<msgId>} for death messages. */
    public static String msgId(ResourceKey<DamageType> key) {
        return Techguns.MODID + "." + key.location().getPath();
    }

    public static void bootstrap(BootstrapContext<DamageType> context) {
        register(context, BULLET, 0.1f, DamageEffects.HURT);
        register(context, EXPLOSION, 0.1f, DamageEffects.HURT);
        register(context, FIRE, 0.1f, DamageEffects.BURNING);
        register(context, ENERGY, 0.1f, DamageEffects.HURT);
        register(context, POISON, 0.0f, DamageEffects.HURT);
        register(context, ICE, 0.1f, DamageEffects.FREEZING);
        register(context, LIGHTNING, 0.1f, DamageEffects.HURT);
        register(context, RADIATION, 0.0f, DamageEffects.HURT);
        register(context, RADIATION_POISONING, 0.0f, DamageEffects.HURT);
        register(context, DARK, 0.1f, DamageEffects.HURT);
        register(context, PHYSICAL, 0.1f, DamageEffects.HURT);
    }

    private static void register(BootstrapContext<DamageType> context, ResourceKey<DamageType> key, float exhaustion, DamageEffects effects) {
        context.register(key, new DamageType(msgId(key), DamageScaling.WHEN_CAUSED_BY_LIVING_NON_PLAYER, exhaustion, effects));
    }
}
